INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Nutzt das objektorientierte Modell Klassen und Objekte?', 2, '[{"text": "Ja", "correct": true, "because": "Grundprinzip der OO-Modellierung"}, {"text": "Nein", "correct": false, "because": "Definiert durch Klassen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für mich beim objektorientierten Modell entscheidend?', 3, '[{"text": "Vererbung", "correct": true, "because": "Wiederverwendung von Strukturen"}, {"text": "Schnelle Installation", "correct": false, "because": "Sekundär"}, {"text": "Minimale Speichergröße", "correct": false, "because": "Funktion wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat das objektorientierte Modell?', 5, '[{"text": "Kapselung", "correct": true, "because": "Daten und Methoden bündeln"}, {"text": "Polymorphismus", "correct": true, "because": "Flexibilität bei Methoden"}, {"text": "Flache Struktur", "correct": false, "because": "Relationaler Ansatz"}, {"text": "Ein Elternteil pro Kind", "correct": false, "because": "Hierarchisches Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt Vererbung. b) Es ist immer tabellenbasiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist relational"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim objektorientierten Modell?', 4, '[{"text": "Klassenstruktur", "correct": false, "because": "Kern des Modells"}, {"text": "Objektbeziehungen", "correct": false, "because": "Wichtig für Logik"}, {"text": "Farbanpassung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Modell komplexe Datenstrukturen unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Objekte für komplexe Daten"}, {"text": "Nein", "correct": false, "because": "Hauptvorteil des Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für Wiederverwendbarkeit im objektorientierten Modell?', 3, '[{"text": "Vererbung", "correct": true, "because": "Eigenschaften weitergeben"}, {"text": "Tabellenjoins", "correct": false, "because": "Relationaler Ansatz"}, {"text": "Baumstruktur", "correct": false, "because": "Hierarchisches Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet mir das objektorientierte Modell?', 5, '[{"text": "Modularität", "correct": true, "because": "Einfache Wartung"}, {"text": "Flexibilität durch Polymorphismus", "correct": true, "because": "Anpassbare Methoden"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Es nutzt Kapselung. b) Es ist für flache Daten besser. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist relational"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein objektorientiertes Modell?', 4, '[{"text": "Klassen", "correct": false, "because": "Grundbausteine"}, {"text": "Methoden", "correct": false, "because": "Definiert Verhalten"}, {"text": "Tabellenlayout", "correct": true, "because": "Relationaler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Modell für einfache Datenbanken geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Aber oft für komplexe genutzt"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen das Modell effektiv?', 4, '[{"text": "Kapselung", "correct": true, "because": "Schützt Daten"}, {"text": "Vererbung", "correct": true, "because": "Reduziert Redundanz"}, {"text": "Hohe Speicherlast", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Modell nur für Programmierung ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Datenbanken"}, {"text": "Ja", "correct": false, "because": "Datenbankanwendung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim objektorientierten Modell?', 3, '[{"text": "Objektstruktur", "correct": true, "because": "Definiert Modell"}, {"text": "Minimale Tiefe", "correct": false, "because": "Tiefe variabel"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Design zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es unterstützt Polymorphismus. b) Es ist baumartig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist hierarchisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkungen hat das objektorientierte Modell?', 5, '[{"text": "Komplexere Abfragen", "correct": true, "because": "Weniger tabellenartig"}, {"text": "Höherer Designaufwand", "correct": true, "because": "Planung nötig"}, {"text": "Einfache Struktur", "correct": false, "because": "Eher komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Modell unwichtig?', 3, '[{"text": "Klassenbeziehungen", "correct": false, "because": "Kern des Modells"}, {"text": "Methodendefinition", "correct": false, "because": "Definiert Verhalten"}, {"text": "Flaches Design", "correct": true, "because": "Relationaler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt das Modell relationale Tabellen?', 3, '[{"text": "Nein", "correct": true, "because": "Objektbasiert, nicht tabellenbasiert"}, {"text": "Ja", "correct": false, "because": "Anderes Paradigma"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Modell für Multimedia-Daten geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Komplexe Objekte möglich"}, {"text": "Nein", "correct": false, "because": "Stärke des Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung passt zum objektorientierten Modell?', 4, '[{"text": "CAD-Systeme", "correct": true, "because": "Komplexe Objekte und Beziehungen"}, {"text": "Einfache Listen", "correct": false, "because": "Zu simpel"}, {"text": "Tabellenkalkulation", "correct": false, "because": "Relationaler Ansatz"}]');
